args.Content:
/* ==========================================================================
   SavorSpot — Theme #19: Obsidian & Espresso Dark Luxury
   Gallery Page Stylesheet (css/gallery.css)
   ========================================================================== */

:root {
  --bg-obsidian: #0a0807;
  --bg-espresso: #120e0c;
  --bg-surface: #191310;
  --bg-elevated: #221a15;

  --accent-gold: #d4af37;
  --accent-champagne: #e7c68e;
  --accent-gold-soft: rgba(212, 175, 55, 0.14);

  --text-primary: #f6f1eb;
  --text-secondary: #c7bdb3;
  --text-muted: #93877b;

  --border-subtle: rgba(231, 198, 142, 0.16);
  --border-strong: rgba(212, 175, 55, 0.45);

  --font-display: "Cormorant Garamond", Georgia, serif;
  --font-sans: "Plus Jakarta Sans", -apple-system, BlinkMacSystemFont, sans-serif;

  --radius-sm: 6px;
  --radius-md: 12px;
  --radius-lg: 18px;
  --shadow-luxury: 0 20px 50px rgba(0, 0, 0, 0.6);
  --transition-fast: 180ms cubic-bezier(0.22, 1, 0.36, 1);
  --transition-med: 280ms cubic-bezier(0.22, 1, 0.36, 1);
}

*,
*::before,
*::after {
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
}

body {
  margin: 0;
  background-color: var(--bg-obsidian);
  background-image:
    radial-gradient(circle at 15% 10%, rgba(212, 175, 55, 0.06), transparent 40%),
    radial-gradient(circle at 85% 25%, rgba(231, 198, 142, 0.04), transparent 45%);
  color: var(--text-primary);
  font-family: var(--font-sans);
  font-size: 16px;
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
}

img {
  display: block;
  max-width: 100%;
}

a {
  color: inherit;
  text-decoration: none;
}

button {
  font-family: inherit;
  cursor: pointer;
}

:focus-visible {
  outline: 2px solid var(--accent-gold);
  outline-offset: 3px;
}

.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

.skip-link {
  position: absolute;
  left: -9999px;
  top: 0;
  background: var(--accent-gold);
  color: var(--bg-obsidian);
  padding: 0.75rem 1.25rem;
  font-weight: 600;
  z-index: 1000;
}

.skip-link:focus {
  left: 1rem;
  top: 1rem;
  border-radius: var(--radius-sm);
}

.container {
  width: min(1240px, 92vw);
  margin-inline: auto;
}

/* Header & Navigation
   ========================================================================== */
.site-header {
  position: sticky;
  top: 0;
  z-index: 50;
  background: rgba(10, 8, 7, 0.9);
  backdrop-filter: blur(12px);
  border-bottom: 1px solid var(--border-subtle);
}

.header-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1.25rem;
  min-height: 76px;
}

.brand {
  display: inline-flex;
  align-items: center;
  gap: 0.75rem;
  flex-shrink: 0;
}

.brand-mark {
  display: grid;
  place-items: center;
  width: 40px;
  height: 40px;
  border-radius: 50%;
  border: 1px solid var(--accent-gold);
  background: var(--bg-surface);
  color: var(--accent-champagne);
  font-family: var(--font-display);
  font-size: 1.45rem;
  font-weight: 700;
}

.brand-text {
  display: flex;
  flex-direction: column;
  line-height: 1.15;
}

.brand-name {
  font-family: var(--font-display);
  font-size: 1.45rem;
  font-weight: 700;
  letter-spacing: 0.04em;
  color: var(--text-primary);
}

.brand-loc {
  font-size: 0.72rem;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--accent-champagne);
}

.primary-nav {
  margin-inline: auto;
}

.nav-list {
  display: flex;
  align-items: center;
  gap: 1.15rem;
  list-style: none;
  margin: 0;
  padding: 0;
}

.nav-link {
  position: relative;
  font-size: 0.88rem;
  font-weight: 500;
  color: var(--text-secondary);
  padding: 0.35rem 0;
  transition: color var(--transition-fast);
  white-space: nowrap;
}

.nav-link:hover,
.nav-link.is-active {
  color: var(--accent-champagne);
}

.nav-link.is-active::after {
  content: "";
  position: absolute;
  left: 0;
  right: 0;
  bottom: -2px;
  height: 2px;
  background: linear-gradient(90deg, var(--accent-gold), var(--accent-champagne));
  border-radius: 2px;
}

.header-actions {
  display: flex;
  align-items: center;
  gap: 0.75rem;
}

.cart-trigger {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  padding: 0.52rem 0.95rem;
  border-radius: 999px;
  border: 1px solid var(--border-strong);
  background: var(--bg-surface);
  color: var(--text-primary);
  font-size: 0.85rem;
  font-weight: 600;
  transition: background-color var(--transition-fast), border-color var(--transition-fast), transform var(--transition-fast);
}

.cart-trigger:hover {
  background: var(--bg-elevated);
  border-color: var(--accent-gold);
  transform: translateY(-1px);
}

.icon-cart {
  width: 18px;
  height: 18px;
  color: var(--accent-champagne);
}

.cart-badge {
  display: inline-grid;
  place-items: center;
  min-width: 22px;
  height: 22px;
  padding-inline: 0.35rem;
  border-radius: 999px;
  background: var(--accent-gold);
  color: var(--bg-obsidian);
  font-size: 0.75rem;
  font-weight: 700;
}

.nav-toggle {
  display: none;
  flex-direction: column;
  justify-content: center;
  gap: 5px;
  width: 42px;
  height: 42px;
  padding: 8px;
  border-radius: var(--radius-sm);
  border: 1px solid var(--border-subtle);
  background: var(--bg-surface);
}

.nav-toggle-bar {
  display: block;
  width: 100%;
  height: 2px;
  background: var(--accent-champagne);
  border-radius: 2px;
}

/* Gallery Hero
   ========================================================================== */
.gallery-hero {
  padding: 4.25rem 0 2.75rem;
  background: linear-gradient(180deg, var(--bg-espresso) 0%, var(--bg-obsidian) 100%);
  border-bottom: 1px solid var(--border-subtle);
  text-align: center;
}

.hero-content {
  max-width: 760px;
}

.eyebrow {
  margin: 0 0 0.75rem;
  font-size: 0.78rem;
  font-weight: 600;
  letter-spacing: 0.22em;
  text-transform: uppercase;
  color: var(--accent-gold);
}

.gallery-hero h1 {
  margin: 0 0 1rem;
  font-family: var(--font-display);
  font-size: clamp(2.4rem, 5vw, 3.8rem);
  font-weight: 600;
  line-height: 1.08;
  color: var(--text-primary);
}

.hero-subtitle {
  margin: 0 auto;
  max-width: 62ch;
  color: var(--text-secondary);
  font-size: 1.02rem;
}

/* Filter Toolbar & Grid
   ========================================================================== */
.gallery-section {
  padding: 3rem 0 5rem;
}

.gallery-toolbar {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: 1rem 1.5rem;
  margin-bottom: 2.25rem;
}

.filter-tabs {
  display: flex;
  flex-wrap: wrap;
  gap: 0.65rem;
}

.filter-tab {
  display: inline-flex;
  align-items: center;
  gap: 0.45rem;
  padding: 0.58rem 1.05rem;
  border-radius: 999px;
  border: 1px solid var(--border-subtle);
  background: var(--bg-espresso);
  color: var(--text-secondary);
  font-size: 0.88rem;
  font-weight: 500;
  transition: all var(--transition-fast);
}

.filter-tab:hover {
  border-color: var(--border-strong);
  color: var(--accent-champagne);
}

.filter-tab.is-active,
.filter-tab[aria-selected="true"] {
  background: linear-gradient(135deg, var(--accent-gold), var(--accent-champagne));
  border-color: transparent;
  color: var(--bg-obsidian);
  font-weight: 700;
}

.tab-count {
  display: inline-grid;
  place-items: center;
  min-width: 20px;
  height: 20px;
  padding-inline: 0.35rem;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.08);
  font-size: 0.74rem;
}

.filter-tab.is-active .tab-count,
.filter-tab[aria-selected="true"] .tab-count {
  background: rgba(10, 8, 7, 0.16);
}

.gallery-status {
  margin: 0;
  font-size: 0.88rem;
  color: var(--text-muted);
}

.gallery-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 1.75rem;
}

.gallery-card {
  background: var(--bg-surface);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-md);
  overflow: hidden;
  transition: transform var(--transition-med), border-color var(--transition-med), box-shadow var(--transition-med);
}

.gallery-card:hover {
  transform: translateY(-4px);
  border-color: var(--border-strong);
  box-shadow: var(--shadow-luxury);
}

.gallery-card[hidden] {
  display: none;
}

.card-figure {
  margin: 0;
  display: flex;
  flex-direction: column;
  height: 100%;
}

.card-media-btn {
  position: relative;
  display: block;
  width: 100%;
  padding: 0;
  border: 0;
  background: var(--bg-espresso);
  overflow: hidden;
  aspect-ratio: 4 / 3;
}

.card-media-btn img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform 420ms cubic-bezier(0.22, 1, 0.36, 1);
}

.gallery-card:hover .card-media-btn img {
  transform: scale(1.05);
}

.card-zoom-hint {
  position: absolute;
  right: 0.85rem;
  bottom: 0.85rem;
  padding: 0.35rem 0.75rem;
  border-radius: 999px;
  background: rgba(10, 8, 7, 0.82);
  border: 1px solid var(--border-strong);
  color: var(--accent-champagne);
  font-size: 0.75rem;
  font-weight: 600;
  letter-spacing: 0.04em;
  opacity: 0;
  transform: translateY(4px);
  transition: opacity var(--transition-fast), transform var(--transition-fast);
}

.gallery-card:hover .card-zoom-hint,
.card-media-btn:focus-visible .card-zoom-hint {
  opacity: 1;
  transform: translateY(0);
}

.card-body {
  display: flex;
  flex-direction: column;
  flex: 1;
  padding: 1.25rem 1.35rem 1.4rem;
}

.card-meta-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.75rem;
  margin-bottom: 0.55rem;
}

.card-tag {
  display: inline-block;
  padding: 0.2rem 0.6rem;
  border-radius: 999px;
  background: var(--accent-gold-soft);
  color: var(--accent-champagne);
  font-size: 0.72rem;
  font-weight: 600;
  letter-spacing: 0.06em;
  text-transform: uppercase;
}

.card-price {
  font-size: 0.84rem;
  font-weight: 600;
  color: var(--accent-gold);
}

.card-title {
  margin: 0 0 0.45rem;
  font-family: var(--font-display);
  font-size: 1.48rem;
  font-weight: 600;
  line-height: 1.2;
  color: var(--text-primary);
}

.card-caption {
  margin: 0 0 1.2rem;
  color: var(--text-secondary);
  font-size: 0.9rem;
  flex: 1;
}

.card-actions {
  display: flex;
  align-items: center;
  gap: 0.65rem;
}

/* Shared Buttons
   ========================================================================== */
.btn-gold,
.btn-outline {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 0.56rem 1rem;
  border-radius: var(--radius-sm);
  font-size: 0.84rem;
  font-weight: 600;
  transition: all var(--transition-fast);
  text-align: center;
}

.btn-gold {
  border: 1px solid transparent;
  background: linear-gradient(135deg, var(--accent-gold), var(--accent-champagne));
  color: var(--bg-obsidian);
}

.btn-gold:hover {
  filter: brightness(1.08);
  transform: translateY(-1px);
}

.btn-outline {
  border: 1px solid var(--border-strong);
  background: transparent;
  color: var(--accent-champagne);
}

.btn-outline:hover {
  background: var(--accent-gold-soft);
  border-color: var(--accent-gold);
}

/* Lightbox Modal
   ========================================================================== */
.lightbox-backdrop {
  position: fixed;
  inset: 0;
  z-index: 120;
  display: grid;
  place-items: center;
  padding: 1.5rem;
  background: rgba(5, 4, 3, 0.88);
  backdrop-filter: blur(8px);
}

.lightbox-backdrop[hidden] {
  display: none;
}

.lightbox-dialog {
  position: relative;
  width: min(960px, 100%);
  max-height: 92vh;
  overflow-y: auto;
  background: var(--bg-espresso);
  border: 1px solid var(--border-strong);
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-luxury);
  display: grid;
  grid-template-columns: 1.35fr 1fr;
}

.lightbox-close {
  position: absolute;
  top: 0.9rem;
  right: 0.9rem;
  z-index: 5;
  width: 38px;
  height: 38px;
  border-radius: 50%;
  border: 1px solid var(--border-strong);
  background: rgba(10, 8, 7, 0.85);
  color: var(--text-primary);
  font-size: 1.4rem;
  line-height: 1;
}

.lightbox-close:hover {
  background: var(--accent-gold);
  color: var(--bg-obsidian);
}

.lightbox-stage {
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--bg-obsidian);
  min-height: 340px;
}

.lightbox-figure {
  margin: 0;
  width: 100%;
  height: 100%;
}

.lightbox-figure img {
  width: 100%;
  height: 100%;
  max-height: 75vh;
  object-fit: cover;
}

.lightbox-nav {
  position: absolute;
  top: 50%;
  transform: translateY(-50%);
  width: 42px;
  height: 42px;
  border-radius: 50%;
  border: 1px solid var(--border-strong);
  background: rgba(10, 8, 7, 0.78);
  color: var(--accent-champagne);
  font-size: 1.15rem;
  transition: background-color var(--transition-fast), color var(--transition-fast);
}

.lightbox-nav:hover {
  background: var(--accent-gold);
  color: var(--bg-obsidian);
}

.lightbox-prev {
  left: 0.85rem;
}

.lightbox-next {
  right: 0.85rem;
}

.lightbox-details {
  display: flex;
  flex-direction: column;
  justify-content: center;
  padding: 2rem 1.85rem;
  gap: 0.75rem;
}

.lightbox-meta-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.75rem;
  padding-right: 2.25rem;
}

.lightbox-counter {
  font-size: 0.82rem;
  color: var(--text-muted);
}

.lightbox-title {
  margin: 0;
  font-family: var(--font-display);
  font-size: 2rem;
  line-height: 1.15;
  color: var(--text-primary);
}

.lightbox-caption {
  margin: 0;
  color: var(--text-secondary);
  font-size: 0.95rem;
}

.lightbox-meta {
  margin: 0;
  font-size: 0.86rem;
  font-weight: 600;
  color: var(--accent-gold);
}

.lightbox-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 0.75rem;
  margin-top: 0.5rem;
}

/* SavorCart Drawer
   ========================================================================== */
.drawer-backdrop {
  position: fixed;
  inset: 0;
  z-index: 100;
  background: rgba(5, 4, 3, 0.72);
  backdrop-filter: blur(4px);
}

.drawer-backdrop[hidden] {
  display: none;
}

.cart-drawer {
  position: fixed;
  top: 0;
  right: 0;
  z-index: 110;
  width: min(420px, 100vw);
  height: 100vh;
  display: flex;
  flex-direction: column;
  background: var(--bg-espresso);
  border-left: 1px solid var(--border-strong);
  box-shadow: -16px 0 40px rgba(0, 0, 0, 0.65);
}

.cart-drawer[hidden] {
  display: none;
}

.cart-header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  padding: 1.35rem 1.4rem;
  border-bottom: 1px solid var(--border-subtle);
}

.cart-header h2 {
  margin: 0;
  font-family: var(--font-display);
  font-size: 1.6rem;
  color: var(--text-primary);
}

.cart-subtitle {
  margin: 0.2rem 0 0;
  font-size: 0.8rem;
  color: var(--text-muted);
}

.cart-close {
  width: 34px;
  height: 34px;
  border-radius: 50%;
  border: 1px solid var(--border-subtle);
  background: var(--bg-surface);
  color: var(--text-primary);
  font-size: 1.3rem;
  line-height: 1;
}

.cart-body {
  flex: 1;
  overflow-y: auto;
  padding: 1.25rem 1.4rem;
  display: flex;
  flex-direction: column;
  gap: 0.9rem;
}

.cart-empty {
  margin: auto 0;
  text-align: center;
  color: var(--text-muted);
  padding: 2rem 1rem;
}

.cart-item {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.85rem;
  padding: 0.9rem;
  border-radius: var(--radius-md);
  background: var(--bg-surface);
  border: 1px solid var(--border-subtle);
}

.cart-item-info {
  min-width: 0;
}

.cart-item-title {
  margin: 0 0 0.2rem;
  font-weight: 600;
  font-size: 0.94rem;
  color: var(--text-primary);
}

.cart-item-price {
  margin: 0;
  font-size: 0.82rem;
  color: var(--accent-champagne);
}

.cart-item-controls {
  display: flex;
  align-items: center;
  gap: 0.4rem;
  flex-shrink: 0;
}

.qty-btn,
.remove-btn {
  width: 28px;
  height: 28px;
  border-radius: var(--radius-sm);
  border: 1px solid var(--border-subtle);
  background: var(--bg-elevated);
  color: var(--text-primary);
  font-weight: 700;
}

.qty-btn:hover,
.remove-btn:hover {
  border-color: var(--accent-gold);
  color: var(--accent-champagne);
}

.qty-value {
  min-width: 22px;
  text-align: center;
  font-size: 0.88rem;
  font-weight: 600;
}

.cart-footer {
  padding: 1.25rem 1.4rem 1.5rem;
  border-top: 1px solid var(--border-subtle);
  background: var(--bg-surface);
}

.cart-summary-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 1rem;
  font-size: 1rem;
}

.cart-summary-row strong {
  color: var(--accent-champagne);
  font-size: 1.15rem;
}

.cart-footer-actions {
  display: grid;
  grid-template-columns: 1fr 1.4fr;
  gap: 0.75rem;
}

/* Toast Notifications
   ========================================================================== */
.toast-container {
  position: fixed;
  right: 1.25rem;
  bottom: 1.25rem;
  z-index: 150;
  display: flex;
  flex-direction: column;
  gap: 0.6rem;
  pointer-events: none;
}

.toast {
  padding: 0.8rem 1.15rem;
  border-radius: var(--radius-md);
  background: var(--bg-elevated);
  border: 1px solid var(--border-strong);
  color: var(--text-primary);
  font-size: 0.88rem;
  font-weight: 500;
  box-shadow: var(--shadow-luxury);
  animation: toastSlideIn 220ms ease-out forwards;
}

@keyframes toastSlideIn {
  from {
    opacity: 0;
    transform: translateY(10px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

/* Footer
   ========================================================================== */
.site-footer {
  background: var(--bg-espresso);
  border-top: 1px solid var(--border-subtle);
  padding: 3.5rem 0 1.75rem;
}

.footer-grid {
  display: grid;
  grid-template-columns: 1.5fr 1fr 1fr 1.1fr;
  gap: 2rem;
  margin-bottom: 2.5rem;
}

.footer-copy,
.footer-meta {
  color: var(--text-secondary);
  font-size: 0.88rem;
  margin: 0.75rem 0 0;
}

.footer-heading {
  margin: 0 0 0.9rem;
  font-family: var(--font-display);
  font-size: 1.22rem;
  color: var(--accent-champagne);
}

.footer-links {
  list-style: none;
  margin: 0;
  padding: 0;
  display: grid;
  gap: 0.5rem;
}

.footer-links a {
  color: var(--text-secondary);
  font-size: 0.88rem;
  transition: color var(--transition-fast);
}

.footer-links a:hover {
  color: var(--accent-gold);
}

.footer-bottom {
  padding-top: 1.5rem;
  border-top: 1px solid var(--border-subtle);
  color: var(--text-muted);
  font-size: 0.82rem;
  text-align: center;
}

/* Responsive Breakpoints
   ========================================================================== */
@media (max-width: 1080px) {
  .nav-toggle {
    display: flex;
  }

  .primary-nav {
    position: fixed;
    top: 76px;
    left: 0;
    right: 0;
    background: var(--bg-espresso);
    border-bottom: 1px solid var(--border-strong);
    padding: 1.25rem 1.5rem;
    display: none;
  }

  .primary-nav.is-open {
    display: block;
  }

  .nav-list {
    flex-direction: column;
    align-items: flex-start;
    gap: 0.85rem;
  }

  .gallery-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .footer-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

@media (max-width: 760px) {
  .lightbox-dialog {
    grid-template-columns: 1fr;
  }

  .lightbox-stage {
    min-height: 240px;
  }

  .gallery-grid {
    grid-template-columns: 1fr;
  }

  .footer-grid {
    grid-template-columns: 1fr;
  }
}

/* ==========================================================================
   SavorSpot — Culinary & Ambiance Gallery Interactivity (js/gallery.js)
   ========================================================================== */

(function () {
  "use strict";

  const CART_STORAGE_KEY = "savorCart";

  const navToggle = document.getElementById("navToggle");
  const primaryNav = document.getElementById("primaryNav");

  const filterTabs = Array.from(document.querySelectorAll(".filter-tab"));
  const galleryCards = Array.from(document.querySelectorAll(".gallery-card"));
  const galleryStatus = document.getElementById("galleryStatus");

  const lightbox = document.getElementById("galleryLightbox");
  const lightboxClose = document.getElementById("lightboxClose");
  const lightboxPrev = document.getElementById("lightboxPrev");
  const lightboxNext = document.getElementById("lightboxNext");
  const lightboxImage = document.getElementById("lightboxImage");
  const lightboxCategory = document.getElementById("lightboxCategory");
  const lightboxCounter = document.getElementById("lightboxCounter");
  const lightboxTitle = document.getElementById("lightboxTitle");
  const lightboxCaption = document.getElementById("lightboxCaption");
  const lightboxMeta = document.getElementById("lightboxMeta");
  const lightboxAddCart = document.getElementById("lightboxAddCart");
  const lightboxReserveLink = document.getElementById("lightboxReserveLink");

  const cartTrigger = document.getElementById("cartTrigger");
  const cartDrawer = document.getElementById("savorCart");
  const cartBackdrop = document.getElementById("cartBackdrop");
  const cartClose = document.getElementById("cartClose");
  const cartBadge = document.getElementById("cartBadge");
  const cartItemsContainer = document.getElementById("cartItemsContainer");
  const cartSubtotal = document.getElementById("cartSubtotal");
  const cartClearBtn = document.getElementById("cartClearBtn");
  const toastContainer = document.getElementById("toastContainer");

  let activeCategory = "all";
  let currentLightboxIndex = 0;
  let lastFocusedElement = null;

  /* ------------------------------------------------------------------------
     Utility Helpers
     ------------------------------------------------------------------------ */
  function formatPKR(amount) {
    return "PKR " + Number(amount || 0).toLocaleString("en-PK");
  }

  function showToast(message) {
    if (!toastContainer) return;
    const toast = document.createElement("div");
    toast.className = "toast";
    toast.textContent = message;
    toastContainer.appendChild(toast);

    window.setTimeout(function () {
      toast.remove();
    }, 2800);
  }

  /* ------------------------------------------------------------------------
     Mobile Navigation Toggle
     ------------------------------------------------------------------------ */
  if (navToggle && primaryNav) {
    navToggle.addEventListener("click", function () {
      const expanded = navToggle.getAttribute("aria-expanded") === "true";
      navToggle.setAttribute("aria-expanded", String(!expanded));
      primaryNav.classList.toggle("is-open", !expanded);
    });
  }

  /* ------------------------------------------------------------------------
     Gallery Category Filtering
     ------------------------------------------------------------------------ */
  function getVisibleCards() {
    return galleryCards.filter(function (card) {
      return !card.hidden;
    });
  }

  function applyFilter(category) {
    activeCategory = category;

    filterTabs.forEach(function (tab) {
      const isSelected = tab.dataset.category === category;
      tab.classList.toggle("is-active", isSelected);
      tab.setAttribute("aria-selected", String(isSelected));
    });

    let visibleCount = 0;
    galleryCards.forEach(function (card) {
      const matches = category === "all" || card.dataset.category === category;
      card.hidden = !matches;
      if (matches) visibleCount += 1;
    });

    if (galleryStatus) {
      galleryStatus.textContent =
        visibleCount === 1
          ? "Showing 1 curated moment"
          : "Showing " + visibleCount + " curated moments";
    }
  }

  filterTabs.forEach(function (tab) {
    tab.addEventListener("click", function () {
      applyFilter(tab.dataset.category || "all");
    });
  });

  /* ------------------------------------------------------------------------
     Lightbox Preview Modal
     ------------------------------------------------------------------------ */
  function renderLightbox(index) {
    const visibleCards = getVisibleCards();
    if (!visibleCards.length || !lightbox) return;

    currentLightboxIndex = (index + visibleCards.length) % visibleCards.length;
    const card = visibleCards[currentLightboxIndex];
    const img = card.querySelector("img");

    if (lightboxImage && img) {
      lightboxImage.src = img.getAttribute("src") || "";
      lightboxImage.alt = img.getAttribute("alt") || card.dataset.title || "";
    }

    if (lightboxCategory) {
      lightboxCategory.textContent = card.dataset.categoryLabel || "";
    }
    if (lightboxCounter) {
      lightboxCounter.textContent =
        currentLightboxIndex + 1 + " / " + visibleCards.length;
    }
    if (lightboxTitle) {
      lightboxTitle.textContent = card.dataset.title || "";
    }
    if (lightboxCaption) {
      lightboxCaption.textContent = card.dataset.caption || "";
    }
    if (lightboxMeta) {
      lightboxMeta.textContent = card.dataset.meta || "";
    }

    const isOrderable = card.dataset.orderable === "true";
    if (lightboxAddCart) {
      lightboxAddCart.hidden = !isOrderable;
      lightboxAddCart.dataset.id = card.dataset.id || "";
      lightboxAddCart.dataset.title = card.dataset.title || "";
      lightboxAddCart.dataset.price = card.dataset.price || "0";
    }
    if (lightboxReserveLink) {
      lightboxReserveLink.hidden = isOrderable;
    }
  }

  function openLightbox(card) {
    const visibleCards = getVisibleCards();
    const index = visibleCards.indexOf(card);
    if (index === -1 || !lightbox) return;

    lastFocusedElement = document.activeElement;
    renderLightbox(index);
    lightbox.hidden = false;
    document.body.style.overflow = "hidden";
    if (lightboxClose) lightboxClose.focus();
  }

  function closeLightbox() {
    if (!lightbox || lightbox.hidden) return;
    lightbox.hidden = true;
    document.body.style.overflow = "";
    if (lastFocusedElement && typeof lastFocusedElement.focus === "function") {
      lastFocusedElement.focus();
    }
  }

  galleryCards.forEach(function (card) {
    const mediaBtn = card.querySelector(".card-media-btn");
    const previewBtn = card.querySelector(".btn-preview");

    if (mediaBtn) {
      mediaBtn.addEventListener("click", function () {
        openLightbox(card);
      });
    }
    if (previewBtn) {
      previewBtn.addEventListener("click", function () {
        openLightbox(card);
      });
    }
  });

  if (lightboxClose) {
    lightboxClose.addEventListener("click", closeLightbox);
  }
  if (lightboxPrev) {
    lightboxPrev.addEventListener("click", function () {
      renderLightbox(currentLightboxIndex - 1);
    });
  }
  if (lightboxNext) {
    lightboxNext.addEventListener("click", function () {
      renderLightbox(currentLightboxIndex + 1);
    });
  }
  if (lightbox) {
    lightbox.addEventListener("click", function (event) {
      if (event.target === lightbox) closeLightbox();
    });
  }

  /* ------------------------------------------------------------------------
     Shared "savorCart" Drawer & localStorage Sync
     ------------------------------------------------------------------------ */
  function readCart() {
    try {
      const raw = window.localStorage.getItem(CART_STORAGE_KEY);
      if (!raw) return [];
      const parsed = JSON.parse(raw);
      return Array.isArray(parsed) ? parsed : [];
    } catch (_err) {
      return [];
    }
  }

  function writeCart(items) {
    try {
      window.localStorage.setItem(CART_STORAGE_KEY, JSON.stringify(items));
    } catch (_err) {
      showToast("Unable to save order in local storage.");
    }
    renderCart();
  }

  function addItemToCart(item) {
    if (!item || !item.id || !item.title) return;
    const cart = readCart();
    const existing = cart.find(function (entry) {
      return entry.id === item.id;
    });

    if (existing) {
      existing.qty = (Number(existing.qty) || 1) + 1;
    } else {
      cart.push({
        id: item.id,
        title: item.title,
        price: Number(item.price) || 0,
        qty: 1
      });
    }

    writeCart(cart);
    showToast("Added " + item.title + " to your SavorSpot order.");
  }

  function updateItemQty(id, delta) {
    const cart = readCart();
    const updated = cart
      .map(function (entry) {
        if (entry.id !== id) return entry;
        return {
          id: entry.id,
          title: entry.title,
          price: entry.price,
          qty: (Number(entry.qty) || 1) + delta
        };
      })
      .filter(function (entry) {
        return entry.qty > 0;
      });

    writeCart(updated);
  }

  function renderCart() {
    const cart = readCart();
    const totalCount = cart.reduce(function (sum, item) {
      return sum + (Number(item.qty) || 1);
    }, 0);
    const subtotalAmount = cart.reduce(function (sum, item) {
      return sum + (Number(item.price) || 0) * (Number(item.qty) || 1);
    }, 0);

    if (cartBadge) {
      cartBadge.textContent = String(totalCount);
    }
    if (cartSubtotal) {
      cartSubtotal.textContent = formatPKR(subtotalAmount);
    }

    if (!cartItemsContainer) return;
    cartItemsContainer.innerHTML = "";

    if (!cart.length) {
      const emptyEl = document.createElement("p");
      emptyEl.className = "cart-empty";
      emptyEl.textContent =
        "Your order drawer is currently empty. Add signature plates, elixirs, or desserts from the gallery or menu.";
      cartItemsContainer.appendChild(emptyEl);
      return;
    }

    cart.forEach(function (item) {
      const row = document.createElement("div");
      row.className = "cart-item";

      const info = document.createElement("div");
      info.className = "cart-item-info";

      const title = document.createElement("p");
      title.className = "cart-item-title";
      title.textContent = item.title;

      const price = document.createElement("p");
      price.className = "cart-item-price";
      price.textContent = formatPKR(item.price);

      info.appendChild(title);
      info.appendChild(price);

      const controls = document.createElement("div");
      controls.className = "cart-item-controls";

      const decBtn = document.createElement("button");
      decBtn.type = "button";
      decBtn.className = "qty-btn";
      decBtn.textContent = "−";
      decBtn.setAttribute("aria-label", "Decrease quantity of " + item.title);
      decBtn.addEventListener("click", function () {
        updateItemQty(item.id, -1);
      });

      const qtyVal = document.createElement("span");
      qtyVal.className = "qty-value";
      qtyVal.textContent = String(item.qty || 1);

      const incBtn = document.createElement("button");
      incBtn.type = "button";
      incBtn.className = "qty-btn";
      incBtn.textContent = "+";
      incBtn.setAttribute("aria-label", "Increase quantity of " + item.title);
      incBtn.addEventListener("click", function () {
        updateItemQty(item.id, 1);
      });

      const removeBtn = document.createElement("button");
      removeBtn.type = "button";
      removeBtn.className = "remove-btn";
      removeBtn.textContent = "×";
      removeBtn.setAttribute("aria-label", "Remove " + item.title + " from order");
      removeBtn.addEventListener("click", function () {
        updateItemQty(item.id, -(Number(item.qty) || 1));
      });

      controls.appendChild(decBtn);
      controls.appendChild(qtyVal);
      controls.appendChild(incBtn);
      controls.appendChild(removeBtn);

      row.appendChild(info);
      row.appendChild(controls);
      cartItemsContainer.appendChild(row);
    });
  }

  function openCartDrawer() {
    if (!cartDrawer || !cartBackdrop) return;
    lastFocusedElement = document.activeElement;
    cartDrawer.hidden = false;
    cartBackdrop.hidden = false;
    if (cartTrigger) cartTrigger.setAttribute("aria-expanded", "true");
    document.body.style.overflow = "hidden";
    if (cartClose) cartClose.focus();
  }

  function closeCartDrawer() {
    if (!cartDrawer || !cartBackdrop || cartDrawer.hidden) return;
    cartDrawer.hidden = true;
    cartBackdrop.hidden = true;
    if (cartTrigger) cartTrigger.setAttribute("aria-expanded", "false");
    document.body.style.overflow = "";
    if (lastFocusedElement && typeof lastFocusedElement.focus === "function") {
      lastFocusedElement.focus();
    }
  }

  if (cartTrigger) {
    cartTrigger.addEventListener("click", openCartDrawer);
  }
  if (cartClose) {
    cartClose.addEventListener("click", closeCartDrawer);
  }
  if (cartBackdrop) {
    cartBackdrop.addEventListener("click", closeCartDrawer);
  }
  if (cartClearBtn) {
    cartClearBtn.addEventListener("click", function () {
      writeCart([]);
      showToast("Cleared your SavorSpot order.");
    });
  }

  galleryCards.forEach(function (card) {
    const addBtn = card.querySelector(".btn-add-cart");
    if (!addBtn) return;

    addBtn.addEventListener("click", function () {
      addItemToCart({
        id: card.dataset.id,
        title: card.dataset.title,
        price: Number(card.dataset.price) || 0
      });
    });
  });

  if (lightboxAddCart) {
    lightboxAddCart.addEventListener("click", function () {
      addItemToCart({
        id: lightboxAddCart.dataset.id,
        title: lightboxAddCart.dataset.title,
        price: Number(lightboxAddCart.dataset.price) || 0
      });
    });
  }

  /* ------------------------------------------------------------------------
     Global Keyboard & Cross-Tab Storage Listeners
     ------------------------------------------------------------------------ */
  document.addEventListener("keydown", function (event) {
    if (lightbox && !lightbox.hidden) {
      if (event.key === "Escape") closeLightbox();
      if (event.key === "ArrowLeft") renderLightbox(currentLightboxIndex - 1);
      if (event.key === "ArrowRight") renderLightbox(currentLightboxIndex + 1);
      return;
    }

    if (cartDrawer && !cartDrawer.hidden && event.key === "Escape") {
      closeCartDrawer();
    }
  });

  window.addEventListener("storage", function (event) {
    if (event.key === CART_STORAGE_KEY) {
      renderCart();
    }
  });

  // Initial sync on load
  applyFilter(activeCategory);
  renderCart();
})();
